def fda_drug_lookup(session_id, drug_name, max_results=None, **_extra):
    import json, os, datetime, re, time, hashlib, random

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0466000" if __import__("os").path.isdir("./environment_mix/0466000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now_iso():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _parse_dt(s):
        if s is None:
            return None
        if isinstance(s, (int, float)):
            return datetime.datetime.utcfromtimestamp(s)
        if isinstance(s, str):
            ss = s.strip()
            if ss.endswith("Z"):
                ss = ss[:-1]
            try:
                return datetime.datetime.fromisoformat(ss)
            except Exception:
                return None
        return None

    _CROCKFORD = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
    def _ulid():
        # 48-bit time (ms) + 80-bit randomness => 26 chars
        ms = int(time.time() * 1000)
        time_part = ms & ((1 << 48) - 1)
        rand_part = random.getrandbits(80)
        v = (time_part << 80) | rand_part
        out = []
        for _ in range(26):
            out.append(_CROCKFORD[v & 31])
            v >>= 5
        return "".join(reversed(out))

    def _new_id(prefix):
        return f"{prefix}{_ulid()}"

    def _norm_text(s):
        return " ".join(str(s).strip().lower().split())

    def _norm_cache_key(tool, fingerprint_obj):
        payload = json.dumps(fingerprint_obj, sort_keys=True, separators=(",", ":"))
        h = hashlib.sha256(payload.encode("utf-8")).hexdigest()
        return f"{tool}:{h}"

    def _find_session(sessions, sid):
        for r in sessions:
            if r.get("id") == sid:
                return r
        return None

    def _is_session_usable(sess):
        if not sess:
            return False
        if sess.get("status") != "active":
            return False
        exp = _parse_dt(sess.get("expires_at"))
        if exp is not None and exp <= datetime.datetime.utcnow():
            return False
        return True

    def _rollup_key(scope, session_id_val, tool_name_val, window, window_start):
        return (scope, session_id_val, tool_name_val, window, window_start)

    def _get_or_create_rollup(rollups, scope, session_id_val, tool_name_val, window, window_start, now_iso):
        for r in rollups:
            if (r.get("scope"), r.get("session_id"), r.get("tool_name"), r.get("window"), r.get("window_start")) == _rollup_key(scope, session_id_val, tool_name_val, window, window_start):
                return r
        row = {
            "id": _new_id("hcs_roll_"),
            "scope": scope,
            "session_id": session_id_val,
            "tool_name": tool_name_val,
            "window": window,
            "window_start": window_start,
            "request_count": 0,
            "success_count": 0,
            "error_count": 0,
            "cache_hit_count": 0,
            "upstream_call_count": 0,
            "total_duration_ms": 0,
            "created_at": now_iso,
            "updated_at": now_iso,
        }
        rollups.append(row)
        return row

    def _inc_rollups(rollups, session_id_val, tool_name_val, succeeded, cache_hit, duration_ms, now_iso):
        # Increment for (session, all tools), (session, tool), (global, all tools), (global, tool)
        targets = [
            ("session", session_id_val, None),
            ("session", session_id_val, tool_name_val),
            ("global", None, None),
            ("global", None, tool_name_val),
        ]
        for scope, sid, tname in targets:
            r = _get_or_create_rollup(rollups, scope, sid, tname, "all_time", None, now_iso)
            r["request_count"] = int(r.get("request_count", 0)) + 1
            if succeeded:
                r["success_count"] = int(r.get("success_count", 0)) + 1
            else:
                r["error_count"] = int(r.get("error_count", 0)) + 1
            if cache_hit:
                r["cache_hit_count"] = int(r.get("cache_hit_count", 0)) + 1
            upstream_inc = 0 if cache_hit else 1
            r["upstream_call_count"] = int(r.get("upstream_call_count", 0)) + upstream_inc
            r["total_duration_ms"] = int(r.get("total_duration_ms", 0)) + int(duration_ms or 0)
            # Maintain invariants defensively
            if r["success_count"] + r["error_count"] > r["request_count"]:
                r["request_count"] = r["success_count"] + r["error_count"]
            if r["cache_hit_count"] > r["request_count"]:
                r["cache_hit_count"] = r["request_count"]
            if r["upstream_call_count"] < 0:
                r["upstream_call_count"] = 0
            r["updated_at"] = now_iso

    # --- validate inputs ---
    if not isinstance(session_id, str) or not re.match(r"^hcs_sess_[0-9A-HJKMNP-TV-Z]{10,}$", session_id or ""):
        return _err("VALIDATION_ERROR", "session_id is invalid", field="session_id")
    if not isinstance(drug_name, str) or not drug_name.strip():
        return _err("VALIDATION_ERROR", "drug_name is required", field="drug_name")
    if max_results is None:
        max_results = 10
    if not isinstance(max_results, int) or max_results < 1 or max_results > 100:
        return _err("VALIDATION_ERROR", "max_results must be between 1 and 100", field="max_results")

    tool_name = "fda_drug_lookup"
    start = time.time()
    now_iso = _now_iso()

    sessions = _load("sessions.json")
    sess = _find_session(sessions, session_id)
    if not _is_session_usable(sess):
        return _err("UNAUTHORIZED", "Session is not active; create a new session to continue", session_id=session_id)

    # Prepare request record (received -> running -> terminal)
    tool_requests = _load("tool_requests.json")
    cached_responses = _load("cached_responses.json")
    usage_rollups = _load("usage_rollups.json")

    fingerprint = {"drug_name": _norm_text(drug_name), "max_results": int(max_results)}
    cache_key = _norm_cache_key(tool_name, fingerprint)

    req_id = _new_id("hcs_req_")
    req_row = {
        "id": req_id,
        "session_id": session_id,
        "tool_name": tool_name,
        "input_params": {"session_id": session_id, "drug_name": drug_name, "max_results": max_results},
        "normalized_cache_key": cache_key,
        "status": "received",
        "http_status": None,
        "error_code": None,
        "error_message": None,
        "duration_ms": None,
        "result_count": None,
        "cache_hit": False,
        "created_at": now_iso,
        "updated_at": now_iso,
    }
    tool_requests.append(req_row)

    # transition to running
    req_row["status"] = "running"
    req_row["updated_at"] = _now_iso()
    sess["last_seen_at"] = req_row["updated_at"]
    sess["updated_at"] = req_row["updated_at"]

    # Serve from cache if possible
    cache_row = None
    now_dt = datetime.datetime.utcnow()
    for cr in cached_responses:
        if cr.get("tool_name") == tool_name and cr.get("cache_key") == cache_key:
            cache_row = cr
            break

    if cache_row and cache_row.get("status") == "fresh":
        exp = _parse_dt(cache_row.get("expires_at"))
        if exp is None or exp > now_dt:
            duration_ms = int(max(0, (time.time() - start) * 1000))
            req_row["status"] = "succeeded"
            req_row["http_status"] = 200
            req_row["error_code"] = None
            req_row["error_message"] = None
            req_row["duration_ms"] = duration_ms
            req_row["cache_hit"] = True
            payload = cache_row.get("response_payload")
            # Determine result_count best-effort
            rc = None
            if isinstance(payload, dict):
                if isinstance(payload.get("results"), list):
                    rc = len(payload.get("results"))
                elif isinstance(payload.get("items"), list):
                    rc = len(payload.get("items"))
            req_row["result_count"] = rc if rc is not None else 0
            req_row["updated_at"] = _now_iso()

            _inc_rollups(usage_rollups, session_id, tool_name, True, True, duration_ms, req_row["updated_at"])
            _save("sessions.json", sessions)
            _save("tool_requests.json", tool_requests)
            _save("usage_rollups.json", usage_rollups)

            return {
                "request": {"id": req_row["id"], "status": req_row["status"], "cache_hit": True, "duration_ms": duration_ms},
                "data": payload,
            }

    # No fresh cache => produce deterministic offline "openfda-like" results
    try:
        dn = _norm_text(drug_name)
        base = hashlib.sha256(dn.encode("utf-8")).hexdigest()
        n = int(max_results)
        results = []
        for i in range(n):
            h = hashlib.sha256((base + f":{i}").encode("utf-8")).hexdigest()
            brand = drug_name.strip().title()
            generic = dn.split()[0].title() if dn else drug_name.strip().title()
            results.append({
                "id": f"openfda_lbl_{h[:16]}",
                "brand_name": brand if i % 2 == 0 else f"{brand} {i+1}",
                "generic_name": generic,
                "manufacturer_name": "Offline OpenFDA (simulated)",
                "spl_set_id": h[:32],
                "purpose": "Information-only offline lookup; not a substitute for professional medical advice.",
            })
        payload = {"drug_name": drug_name, "results": results}
        http_status = 200
        succeeded = True
        error_code = None
        error_message = None
    except Exception as e:
        payload = None
        http_status = 500
        succeeded = False
        error_code = "INTERNAL_ERROR"
        error_message = str(e)

    duration_ms = int(max(0, (time.time() - start) * 1000))
    if duration_ms < 0:
        return _err("VALIDATION_ERROR", "duration_ms must be >= 0", field="duration_ms")

    if succeeded:
        req_row["status"] = "succeeded"
        req_row["http_status"] = http_status
        req_row["error_code"] = None
        req_row["error_message"] = None
        req_row["duration_ms"] = duration_ms
        req_row["result_count"] = len(payload.get("results", [])) if isinstance(payload, dict) else 0
        req_row["cache_hit"] = False
        req_row["updated_at"] = _now_iso()

        # Upsert cache row (unique tool_name, cache_key)
        ttl_seconds = 24 * 3600
        expires_at = (datetime.datetime.utcnow() + datetime.timedelta(seconds=ttl_seconds)).replace(microsecond=0).isoformat() + "Z"
        if cache_row is None:
            cache_row = {
                "id": _new_id("hcs_cache_"),
                "tool_name": tool_name,
                "cache_key": cache_key,
                "request_fingerprint": fingerprint,
                "response_payload": payload,
                "status": "fresh",
                "source": "openfda",
                "etag": None,
                "expires_at": expires_at,
                "created_at": now_iso,
                "updated_at": req_row["updated_at"],
            }
            cached_responses.append(cache_row)
        else:
            cache_row["request_fingerprint"] = fingerprint
            cache_row["response_payload"] = payload
            cache_row["status"] = "fresh"
            cache_row["source"] = "openfda"
            cache_row["expires_at"] = expires_at
            cache_row["updated_at"] = req_row["updated_at"]

        _inc_rollups(usage_rollups, session_id, tool_name, True, False, duration_ms, req_row["updated_at"])
        _save("cached_responses.json", cached_responses)
        _save("sessions.json", sessions)
        _save("tool_requests.json", tool_requests)
        _save("usage_rollups.json", usage_rollups)

        return {
            "request": {"id": req_row["id"], "status": req_row["status"], "cache_hit": False, "duration_ms": duration_ms},
            "data": payload,
        }
    else:
        req_row["status"] = "failed"
        req_row["http_status"] = http_status
        req_row["error_code"] = error_code or "UNKNOWN_ERROR"
        req_row["error_message"] = error_message or "Request failed"
        req_row["duration_ms"] = duration_ms
        req_row["result_count"] = 0
        req_row["cache_hit"] = False
        req_row["updated_at"] = _now_iso()

        _inc_rollups(usage_rollups, session_id, tool_name, False, False, duration_ms, req_row["updated_at"])
        _save("sessions.json", sessions)
        _save("tool_requests.json", tool_requests)
        _save("usage_rollups.json", usage_rollups)
        return _err("CONFLICT", "Tool execution failed", request_id=req_row["id"], error_code=req_row["error_code"], error_message=req_row["error_message"])

def pubmed_search(session_id, query, max_results=None, date_range=None, **_extra):
    import json, os, datetime, re, time, hashlib, random

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0466000" if __import__("os").path.isdir("./environment_mix/0466000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now_iso():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _parse_dt(s):
        if s is None:
            return None
        if isinstance(s, (int, float)):
            return datetime.datetime.utcfromtimestamp(s)
        if isinstance(s, str):
            ss = s.strip()
            if ss.endswith("Z"):
                ss = ss[:-1]
            try:
                return datetime.datetime.fromisoformat(ss)
            except Exception:
                return None
        return None

    _CROCKFORD = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
    def _ulid():
        ms = int(time.time() * 1000)
        time_part = ms & ((1 << 48) - 1)
        rand_part = random.getrandbits(80)
        v = (time_part << 80) | rand_part
        out = []
        for _ in range(26):
            out.append(_CROCKFORD[v & 31])
            v >>= 5
        return "".join(reversed(out))

    def _new_id(prefix):
        return f"{prefix}{_ulid()}"

    def _norm_text(s):
        return " ".join(str(s).strip().lower().split())

    def _norm_cache_key(tool, fingerprint_obj):
        payload = json.dumps(fingerprint_obj, sort_keys=True, separators=(",", ":"))
        h = hashlib.sha256(payload.encode("utf-8")).hexdigest()
        return f"{tool}:{h}"

    def _find_session(sessions, sid):
        for r in sessions:
            if r.get("id") == sid:
                return r
        return None

    def _is_session_usable(sess):
        if not sess:
            return False
        if sess.get("status") != "active":
            return False
        exp = _parse_dt(sess.get("expires_at"))
        if exp is not None and exp <= datetime.datetime.utcnow():
            return False
        return True

    def _get_or_create_rollup(rollups, scope, session_id_val, tool_name_val, window, window_start, now_iso):
        for r in rollups:
            if (r.get("scope"), r.get("session_id"), r.get("tool_name"), r.get("window"), r.get("window_start")) == (scope, session_id_val, tool_name_val, window, window_start):
                return r
        row = {
            "id": _new_id("hcs_roll_"),
            "scope": scope,
            "session_id": session_id_val,
            "tool_name": tool_name_val,
            "window": window,
            "window_start": window_start,
            "request_count": 0,
            "success_count": 0,
            "error_count": 0,
            "cache_hit_count": 0,
            "upstream_call_count": 0,
            "total_duration_ms": 0,
            "created_at": now_iso,
            "updated_at": now_iso,
        }
        rollups.append(row)
        return row

    def _inc_rollups(rollups, session_id_val, tool_name_val, succeeded, cache_hit, duration_ms, now_iso):
        targets = [
            ("session", session_id_val, None),
            ("session", session_id_val, tool_name_val),
            ("global", None, None),
            ("global", None, tool_name_val),
        ]
        for scope, sid, tname in targets:
            r = _get_or_create_rollup(rollups, scope, sid, tname, "all_time", None, now_iso)
            r["request_count"] = int(r.get("request_count", 0)) + 1
            if succeeded:
                r["success_count"] = int(r.get("success_count", 0)) + 1
            else:
                r["error_count"] = int(r.get("error_count", 0)) + 1
            if cache_hit:
                r["cache_hit_count"] = int(r.get("cache_hit_count", 0)) + 1
            r["upstream_call_count"] = int(r.get("upstream_call_count", 0)) + (0 if cache_hit else 1)
            r["total_duration_ms"] = int(r.get("total_duration_ms", 0)) + int(duration_ms or 0)
            if r["success_count"] + r["error_count"] > r["request_count"]:
                r["request_count"] = r["success_count"] + r["error_count"]
            if r["cache_hit_count"] > r["request_count"]:
                r["cache_hit_count"] = r["request_count"]
            r["updated_at"] = now_iso

    # validate
    if not isinstance(session_id, str) or not re.match(r"^hcs_sess_[0-9A-HJKMNP-TV-Z]{10,}$", session_id or ""):
        return _err("VALIDATION_ERROR", "session_id is invalid", field="session_id")
    if not isinstance(query, str) or not query.strip():
        return _err("VALIDATION_ERROR", "query is required", field="query")
    if max_results is None:
        max_results = 10
    if not isinstance(max_results, int) or max_results < 1 or max_results > 100:
        return _err("VALIDATION_ERROR", "max_results must be between 1 and 100", field="max_results")
    if date_range is not None:
        if not isinstance(date_range, int) or date_range < 1 or date_range > 100:
            return _err("VALIDATION_ERROR", "date_range must be between 1 and 100 years", field="date_range")

    tool_name = "pubmed_search"
    start = time.time()
    now_iso = _now_iso()

    sessions = _load("sessions.json")
    sess = _find_session(sessions, session_id)
    if not _is_session_usable(sess):
        return _err("UNAUTHORIZED", "Session is not active; create a new session to continue", session_id=session_id)

    tool_requests = _load("tool_requests.json")
    cached_responses = _load("cached_responses.json")
    usage_rollups = _load("usage_rollups.json")

    fingerprint = {"query": _norm_text(query), "max_results": int(max_results), "date_range": int(date_range) if date_range is not None else None}
    cache_key = _norm_cache_key(tool_name, fingerprint)

    req_id = _new_id("hcs_req_")
    req_row = {
        "id": req_id,
        "session_id": session_id,
        "tool_name": tool_name,
        "input_params": {"session_id": session_id, "query": query, "max_results": max_results, "date_range": date_range},
        "normalized_cache_key": cache_key,
        "status": "received",
        "http_status": None,
        "error_code": None,
        "error_message": None,
        "duration_ms": None,
        "result_count": None,
        "cache_hit": False,
        "created_at": now_iso,
        "updated_at": now_iso,
    }
    tool_requests.append(req_row)

    req_row["status"] = "running"
    req_row["updated_at"] = _now_iso()
    sess["last_seen_at"] = req_row["updated_at"]
    sess["updated_at"] = req_row["updated_at"]

    cache_row = None
    now_dt = datetime.datetime.utcnow()
    for cr in cached_responses:
        if cr.get("tool_name") == tool_name and cr.get("cache_key") == cache_key:
            cache_row = cr
            break

    if cache_row and cache_row.get("status") == "fresh":
        exp = _parse_dt(cache_row.get("expires_at"))
        if exp is None or exp > now_dt:
            duration_ms = int(max(0, (time.time() - start) * 1000))
            req_row["status"] = "succeeded"
            req_row["http_status"] = 200
            req_row["duration_ms"] = duration_ms
            req_row["cache_hit"] = True
            payload = cache_row.get("response_payload") or {}
            rc = len(payload.get("results", [])) if isinstance(payload.get("results"), list) else 0
            req_row["result_count"] = rc
            req_row["updated_at"] = _now_iso()

            _inc_rollups(usage_rollups, session_id, tool_name, True, True, duration_ms, req_row["updated_at"])
            _save("sessions.json", sessions)
            _save("tool_requests.json", tool_requests)
            _save("usage_rollups.json", usage_rollups)
            return {"request": {"id": req_row["id"], "status": req_row["status"], "cache_hit": True, "duration_ms": duration_ms}, "data": payload}

    try:
        qn = _norm_text(query)
        base = hashlib.sha256((qn + "|" + str(date_range)).encode("utf-8")).hexdigest()
        n = int(max_results)
        current_year = datetime.datetime.utcnow().year
        min_year = current_year - int(date_range) if date_range is not None else current_year - 50
        results = []
        for i in range(n):
            h = hashlib.sha256((base + f":{i}").encode("utf-8")).hexdigest()
            year = min_year + (int(h[:2], 16) % max(1, (current_year - min_year + 1)))
            results.append({
                "pmid": str(int(h[:10], 16)),
                "title": f"Offline PubMed result for '{query.strip()}' ({i+1})",
                "journal": "Offline PubMed (simulated)",
                "year": int(year),
                "authors": ["Doe J", "Smith A"],
                "abstract": "Simulated literature search result generated offline; verify with official PubMed for clinical use.",
                "url": f"https://pubmed.ncbi.nlm.nih.gov/{str(int(h[:10], 16))}/",
            })
        payload = {"query": query, "date_range_years": date_range, "results": results}
        succeeded = True
        http_status = 200
        error_code = None
        error_message = None
    except Exception as e:
        payload = None
        succeeded = False
        http_status = 500
        error_code = "INTERNAL_ERROR"
        error_message = str(e)

    duration_ms = int(max(0, (time.time() - start) * 1000))
    if duration_ms < 0:
        return _err("VALIDATION_ERROR", "duration_ms must be >= 0", field="duration_ms")

    if succeeded:
        req_row["status"] = "succeeded"
        req_row["http_status"] = http_status
        req_row["error_code"] = None
        req_row["error_message"] = None
        req_row["duration_ms"] = duration_ms
        req_row["result_count"] = len(payload.get("results", [])) if isinstance(payload, dict) else 0
        req_row["cache_hit"] = False
        req_row["updated_at"] = _now_iso()

        ttl_seconds = 6 * 3600
        expires_at = (datetime.datetime.utcnow() + datetime.timedelta(seconds=ttl_seconds)).replace(microsecond=0).isoformat() + "Z"
        if cache_row is None:
            cache_row = {
                "id": _new_id("hcs_cache_"),
                "tool_name": tool_name,
                "cache_key": cache_key,
                "request_fingerprint": fingerprint,
                "response_payload": payload,
                "status": "fresh",
                "source": "pubmed",
                "etag": None,
                "expires_at": expires_at,
                "created_at": now_iso,
                "updated_at": req_row["updated_at"],
            }
            cached_responses.append(cache_row)
        else:
            cache_row["request_fingerprint"] = fingerprint
            cache_row["response_payload"] = payload
            cache_row["status"] = "fresh"
            cache_row["source"] = "pubmed"
            cache_row["expires_at"] = expires_at
            cache_row["updated_at"] = req_row["updated_at"]

