        for r in sessions:
            if r.get("id") == sid:
                return r
        return None

    def _is_session_usable(sess):
        if not sess:
            return False
        if sess.get("status") != "active":
            return False
        exp = _parse_dt(sess.get("expires_at"))
        if exp is not None and exp <= datetime.datetime.utcnow():
            return False
        return True

    def _get_or_create_rollup(rollups, scope, session_id_val, tool_name_val, window, window_start, now_iso):
        for r in rollups:
