        return _err("VALIDATION_ERROR", "topic is required", field="topic")
    if language is None:
        language = "en"
    if not isinstance(language, str) or language not in ("en", "es"):
        return _err("VALIDATION_ERROR", "language must be 'en' or 'es'", field="language")

    tool_name = "health_topics"
    start = time.time()
    now_iso = _now_iso()

