            cache_row["updated_at"] = req_row["updated_at"]

        _inc_rollups(usage_rollups, session_id, tool_name, True, False, duration_ms, req_row["updated_at"])
        _save("cached_responses.json", cached_responses)
        _save("sessions.json", sessions)
        _save("tool_requests.json", tool_requests)
        _save("usage_rollups.json", usage_rollups)
        return {"request": {"id": req_row["id"], "status": req_row["status"], "cache_hit": False, "duration_ms": duration_ms}, "data": payload}
    else:
        req_row["status"] = "failed"
        req_row["http_status"] = http_status
        req_row["error_code"] = error_code or "UNKNOWN_ERROR"
        req_row["error_message"] = error_message or "Request failed"
        req_row["duration_ms"] = duration_ms
        req_row["result_count"] = 0
        req_row["cache_hit"] = False
        req_row["updated_at"] = _now_iso()

        _inc_rollups(usage_rollups, session_id, tool_name, False, False, duration_ms, req_row["updated_at"])
        _save("sessions.json", sessions)
        _save("tool_requests.json", tool_requests)
        _save("usage_rollups.json", usage_rollups)
        return _err("CONFLICT", "Tool execution failed", request_id=req_row["id"], error_code=req_row["error_code"], error_message=req_row["error_message"])

def lookup_icd_code(session_id, code=None, description=None, max_results=None, **_extra):
    import json, os, datetime, re, hashlib, time, uuid

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0466000" if __import__("os").path.isdir("./environment_mix/0466000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    def _now_utc():
        return datetime.datetime.now(datetime.timezone.utc)

    def _iso(dt):
        if isinstance(dt, datetime.datetime):
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc).isoformat().replace("+00:00", "Z")
        return dt

    def _parse_dt(s):
        if s is None:
            return None
        if not isinstance(s, str):
            return None
        try:
            # supports ...Z
            if s.endswith("Z"):
                return datetime.datetime.fromisoformat(s[:-1] + "+00:00")
            return datetime.datetime.fromisoformat(s)
        except ValueError:
            return None

    def _new_id(prefix):
        # ULID-like (not strict ULID), matches required base32-ish charset
        alphabet = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
        ts = int(time.time() * 1000)
        # encode timestamp base32
        out = []
        for _ in range(10):
            out.append(alphabet[ts % 32])
            ts //= 32
        rand = uuid.uuid4().int
        for _ in range(16):
            out.append(alphabet[rand % 32])
            rand //= 32
        return f"{prefix}_" + "".join(reversed(out))

    def _normalize_cache_key(tool, fp):
        # deterministic string: tool|k=v|k=v sorted; values normalized
        items = []
        for k in sorted(fp.keys()):
            v = fp[k]
            if v is None:
                vv = ""
            elif isinstance(v, bool):
                vv = "true" if v else "false"
            else:
                vv = str(v).strip()
            items.append(f"{k}={vv}")
        raw = tool + "|" + "&".join(items)
        return hashlib.sha256(raw.encode("utf-8")).hexdigest()

    def _record_request(req_row, status, duration_ms=None, http_status=None, error_code=None, error_message=None, result_count=None, cache_hit=False, normalized_cache_key=None):
        tool_requests = _load("tool_requests.json")
        usage_rollups = _load("usage_rollups.json")
        sessions = _load("sessions.json")

        # Update req row in tool_requests store
        now = _now_utc()
        now_iso = _iso(now)
        updated = False
        for r in tool_requests:
            if r.get("id") == req_row["id"]:
                # lifecycle transition validation
                transitions = {
                    "received": ["running", "failed"],
                    "running": ["succeeded", "failed"],
                    "succeeded": [],
                    "failed": [],
                }
                cur = r.get("status")
                if status != cur:
                    if status not in transitions.get(cur, []):
                        return _err("INVALID_TRANSITION", f"Illegal tool_requests status transition {cur} -> {status}.")
                r["status"] = status
                r["updated_at"] = now_iso
                if normalized_cache_key is not None:
                    r["normalized_cache_key"] = normalized_cache_key
                r["cache_hit"] = bool(cache_hit)
                if http_status is not None:
                    r["http_status"] = http_status
                if duration_ms is not None:
                    if not isinstance(duration_ms, int) or duration_ms < 0:
                        return _err("VALIDATION_ERROR", "duration_ms must be an integer >= 0.")
                    r["duration_ms"] = duration_ms
                if result_count is not None:
                    if not isinstance(result_count, int) or result_count < 0:
                        return _err("VALIDATION_ERROR", "result_count must be an integer >= 0.")
                    r["result_count"] = result_count

                if status == "failed":
                    if error_code is None or error_message is None:
                        return _err("VALIDATION_ERROR", "Failed requests must include error_code and error_message.")
                    r["error_code"] = str(error_code)
                    r["error_message"] = str(error_message)
                if status == "succeeded":
                    r["error_code"] = None
                    r["error_message"] = None
                updated = True
                break
        if not updated:
            return _err("NOT_FOUND", "tool request not found to update.")

        # Update session last_seen_at if possible
        for s in sessions:
            if s.get("id") == req_row["session_id"]:
                s["last_seen_at"] = now_iso
                s["updated_at"] = now_iso
                break

        # On terminal completion, increment rollups
        if status in ("succeeded", "failed"):
            success = (status == "succeeded")
            duration_add = 0
            for r in tool_requests:
                if r.get("id") == req_row["id"]:
                    duration_add = int(r.get("duration_ms") or 0)
                    break

            def _find_or_create_rollup(scope, session_id_val, tool_name_val, window, window_start):
                for u in usage_rollups:
                    if u.get("scope") == scope and u.get("session_id") == session_id_val and u.get("tool_name") == tool_name_val and u.get("window") == window and u.get("window_start") == window_start:
                        return u
                rid = _new_id("hcs_usage")
                row = {
                    "id": rid,
                    "scope": scope,
                    "session_id": session_id_val,
                    "tool_name": tool_name_val,
                    "window": window,
                    "window_start": window_start,
                    "request_count": 0,
                    "success_count": 0,
                    "error_count": 0,
                    "cache_hit_count": 0,
                    "upstream_call_count": 0,
                    "total_duration_ms": 0,
                    "created_at": now_iso,
                    "updated_at": now_iso,
                }
                usage_rollups.append(row)
                return row

            def _bump(row):
                row["request_count"] += 1
                if success:
                    row["success_count"] += 1
                else:
                    row["error_count"] += 1
                if cache_hit:
                    row["cache_hit_count"] += 1
                # upstream call count is estimated as request_count - cache_hit_count (as per schema guidance)
                row["upstream_call_count"] = max(0, int(row["request_count"]) - int(row["cache_hit_count"]))
                row["total_duration_ms"] += max(0, int(duration_add))
                row["updated_at"] = now_iso
                # invariants check
                if row["success_count"] + row["error_count"] > row["request_count"]:
                    return _err("CONFLICT", "usage_rollups invariant violated: success+error > request_count.")
                if row["cache_hit_count"] > row["request_count"]:
                    return _err("CONFLICT", "usage_rollups invariant violated: cache_hit_count > request_count.")
                if row["request_count"] < 0 or row["success_count"] < 0 or row["error_count"] < 0 or row["cache_hit_count"] < 0 or row["upstream_call_count"] < 0 or row["total_duration_ms"] < 0:
                    return _err("CONFLICT", "usage_rollups invariant violated: negative counters.")
                return None

            # all_time rollups only (tool surface mentions all_time and day; per-call increments are always all_time)
            r1 = _find_or_create_rollup("session", req_row["session_id"], None, "all_time", None)
            e = _bump(r1)
            if e: 
                _save("tool_requests.json", tool_requests)
                _save("sessions.json", sessions)
                _save("usage_rollups.json", usage_rollups)
                return e
            r2 = _find_or_create_rollup("session", req_row["session_id"], req_row["tool_name"], "all_time", None)
            e = _bump(r2)
            if e:
                _save("tool_requests.json", tool_requests)
                _save("sessions.json", sessions)
                _save("usage_rollups.json", usage_rollups)
                return e
            r3 = _find_or_create_rollup("global", None, None, "all_time", None)
            e = _bump(r3)
            if e:
                _save("tool_requests.json", tool_requests)
                _save("sessions.json", sessions)
                _save("usage_rollups.json", usage_rollups)
                return e
            r4 = _find_or_create_rollup("global", None, req_row["tool_name"], "all_time", None)
            e = _bump(r4)
            if e:
                _save("tool_requests.json", tool_requests)
                _save("sessions.json", sessions)
                _save("usage_rollups.json", usage_rollups)
                return e

        _save("tool_requests.json", tool_requests)
        _save("sessions.json", sessions)
        _save("usage_rollups.json", usage_rollups)
        return None

    # ---- Validate inputs ----
    if not isinstance(session_id, str) or not re.match(r"^hcs_sess_[0-9A-HJKMNP-TV-Z]{10,}$", session_id):
        return _err("VALIDATION_ERROR", "session_id is invalid.")
    if code is not None and not isinstance(code, str):
        return _err("VALIDATION_ERROR", "code must be a string.")
    if description is not None and not isinstance(description, str):
        return _err("VALIDATION_ERROR", "description must be a string.")
    if (code is None or code.strip() == "") and (description is None or description.strip() == ""):
        return _err("VALIDATION_ERROR", "Either code or description must be provided.")
    if max_results is None:
        max_results = 20
    if not isinstance(max_results, int) or max_results < 1 or max_results > 100:
        return _err("VALIDATION_ERROR", "max_results must be an integer between 1 and 100.")

    # ---- Resolve session & ensure active ----
    sessions = _load("sessions.json")
    sess = None
    for s in sessions:
        if s.get("id") == session_id:
            sess = s
            break
    if sess is None:
        return _err("NOT_FOUND", "Session not found.")
    now = _now_utc()
    if sess.get("status") != "active":
        return _err("UNAUTHORIZED", "Session is not active; create a new session.")
    exp = _parse_dt(sess.get("expires_at"))
    if exp is not None and exp <= now:
        # Expire it (legal transition) and reject request per business rule
        if sess.get("status") == "active":
            sess["status"] = "expired"
            sess["updated_at"] = _iso(now)
            _save("sessions.json", sessions)
        return _err("UNAUTHORIZED", "Session is expired; create a new session.")

    # ---- Create tool_requests row (received -> running) ----
    tool_requests = _load("tool_requests.json")
    req_id = _new_id("hcs_trq")
    created_at = _iso(now)
    input_params = {"session_id": session_id, "code": code, "description": description, "max_results": max_results}
    # Normalized fingerprint
    fp = {
        "code": (code or "").strip().upper() or None,
        "description": (description or "").strip().lower() or None,
        "max_results": int(max_results),
    }
    cache_key = _normalize_cache_key("lookup_icd_code", fp)

    req_row = {
        "id": req_id,
        "session_id": session_id,
        "tool_name": "lookup_icd_code",
        "input_params": input_params,
        "normalized_cache_key": cache_key,
        "status": "received",
        "http_status": None,
        "error_code": None,
        "error_message": None,
        "duration_ms": None,
        "result_count": None,
        "cache_hit": False,
        "created_at": created_at,
        "updated_at": created_at,
    }
    tool_requests.append(req_row)
    _save("tool_requests.json", tool_requests)

    # transition to running
    run_start = time.perf_counter()
    e = _record_request(req_row, "running", normalized_cache_key=cache_key, cache_hit=False)
    if e:
        return e

    # ---- Cache check ----
    cached_responses = _load("cached_responses.json")
    cache_row = None
    for c in cached_responses:
        if c.get("tool_name") == "lookup_icd_code" and c.get("cache_key") == cache_key:
            cache_row = c
            break

    def _cache_valid(row):
        if row is None:
            return False
        if row.get("status") != "fresh":
            return False
        ex = _parse_dt(row.get("expires_at"))
        return (ex is None) or (ex > _now_utc())

    if _cache_valid(cache_row):
        payload = cache_row.get("response_payload")
        # finalize succeeded from cache
        dur = int((time.perf_counter() - run_start) * 1000)
        results = []
        if isinstance(payload, dict):
            results = payload.get("results") if isinstance(payload.get("results"), list) else []
        e = _record_request(req_row, "succeeded", duration_ms=dur, http_status=200, result_count=len(results), cache_hit=True, normalized_cache_key=cache_key)
        if e:
            return e
        return {
            "session_id": session_id,
            "tool_name": "lookup_icd_code",
            "cache_hit": True,
            "normalized_cache_key": cache_key,
            "results": results,
            "result_count": len(results),
        }

    # ---- Compute results (offline dataset) ----
    # Minimal embedded ICD-10-CM subset; real service would query upstream.
    icd = [
        {"code": "E11.9", "description": "Type 2 diabetes mellitus without complications"},
        {"code": "I10", "description": "Essential (primary) hypertension"},
        {"code": "J45.909", "description": "Unspecified asthma, uncomplicated"},
        {"code": "F41.1", "description": "Generalized anxiety disorder"},
        {"code": "F32.9", "description": "Major depressive disorder, single episode, unspecified"},
        {"code": "M54.5", "description": "Low back pain"},
        {"code": "R07.9", "description": "Chest pain, unspecified"},
        {"code": "J06.9", "description": "Acute upper respiratory infection, unspecified"},
        {"code": "N39.0", "description": "Urinary tract infection, site not specified"},
        {"code": "K21.9", "description": "Gastro-esophageal reflux disease without esophagitis"},
        {"code": "E78.5", "description": "Hyperlipidemia, unspecified"},
        {"code": "U07.1", "description": "COVID-19"},
    ]

    c_norm = (code or "").strip().upper()
    d_norm = (description or "").strip().lower()

    matches = []
    for row in icd:
        ok = True
        if c_norm:
            ok = ok and (row["code"].upper() == c_norm)
        if d_norm:
            ok = ok and (d_norm in row["description"].lower())
        if ok:
            matches.append({"code": row["code"], "description": row["description"]})

    matches = matches[:max_results]
    payload = {
        "session_id": session_id,
        "tool_name": "lookup_icd_code",
        "cache_hit": False,
        "normalized_cache_key": cache_key,
        "results": matches,
        "result_count": len(matches),
    }

    # ---- Upsert cache row ----
    now2 = _now_utc()
    now2_iso = _iso(now2)
    ttl = datetime.timedelta(days=30)
    expires_at = _iso(now2 + ttl)

    if cache_row is None:
        # enforce unique(tool_name, cache_key)
        for c in cached_responses:
            if c.get("tool_name") == "lookup_icd_code" and c.get("cache_key") == cache_key:
                cache_row = c
                break

    if cache_row is None:
        cached_responses.append({
            "id": _new_id("hcs_cache"),
            "tool_name": "lookup_icd_code",
            "cache_key": cache_key,
            "request_fingerprint": fp,
            "response_payload": payload,
            "status": "fresh",
            "source": "icd10cm",
            "etag": None,
            "expires_at": expires_at,
            "created_at": now2_iso,
            "updated_at": now2_iso,
        })
    else:
        # transition stale/invalid->fresh is allowed; fresh->fresh effectively refresh.
        cache_row["request_fingerprint"] = fp
        cache_row["response_payload"] = payload
        cache_row["status"] = "fresh"
        cache_row["source"] = "icd10cm"
        cache_row["expires_at"] = expires_at
        cache_row["updated_at"] = now2_iso

    _save("cached_responses.json", cached_responses)

    # ---- finalize request ----
    dur = int((time.perf_counter() - run_start) * 1000)
    e = _record_request(req_row, "succeeded", duration_ms=dur, http_status=200, result_count=len(matches), cache_hit=False, normalized_cache_key=cache_key)
    if e:
        return e

    return payload

def get_usage_stats(session_id, window=None, day=None, **_extra):
    import json, os, datetime, re, time, uuid

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0466000" if __import__("os").path.isdir("./environment_mix/0466000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    def _now_utc():
        return datetime.datetime.now(datetime.timezone.utc)

    def _iso(dt):
        if isinstance(dt, datetime.datetime):
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc).isoformat().replace("+00:00", "Z")
        return dt

    def _new_id(prefix):
        alphabet = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
        ts = int(time.time() * 1000)
        out = []
        for _ in range(10):
            out.append(alphabet[ts % 32])
            ts //= 32
        rand = uuid.uuid4().int
        for _ in range(16):
            out.append(alphabet[rand % 32])
            rand //= 32
        return f"{prefix}_" + "".join(reversed(out))

    def _parse_day(s):
        if not isinstance(s, str):
            return None
        try:
            d = datetime.date.fromisoformat(s)
            return d
        except ValueError:
            return None

    # ---- Validate inputs ----
    if not isinstance(session_id, str) or not re.match(r"^hcs_sess_[0-9A-HJKMNP-TV-Z]{10,}$", session_id):
        return _err("VALIDATION_ERROR", "session_id is invalid.")
    if window is None:
        window = "all_time"
    if not isinstance(window, str) or window not in ("all_time", "day"):
        return _err("VALIDATION_ERROR", "window must be one of: all_time, day.")
    day_date = None
    if window == "day":
        day_date = _parse_day(day)
        if day_date is None:
            return _err("VALIDATION_ERROR", "day must be provided as YYYY-MM-DD when window='day'.")

    # ---- Ensure session exists ----
    sessions = _load("sessions.json")
    sess = None
    for s in sessions:
        if s.get("id") == session_id:
            sess = s
            break
    if sess is None:
        return _err("NOT_FOUND", "Session not found.")

    # ---- Record this tool invocation lifecycle ----
    tool_requests = _load("tool_requests.json")
    now = _now_utc()
    created_at = _iso(now)
    req_row = {
        "id": _new_id("hcs_trq"),
        "session_id": session_id,
        "tool_name": "get_usage_stats",
        "input_params": {"session_id": session_id, "window": window, "day": day},
        "normalized_cache_key": None,
        "status": "received",
        "http_status": None,
        "error_code": None,
        "error_message": None,
        "duration_ms": None,
        "result_count": None,
        "cache_hit": False,
        "created_at": created_at,
        "updated_at": created_at,
    }
    tool_requests.append(req_row)
    _save("tool_requests.json", tool_requests)

    start = time.perf_counter()

    # transition to running
    def _update_req(status, duration_ms=None, error_code=None, error_message=None, http_status=None, result_count=None):
        trs = _load("tool_requests.json")
        now2 = _iso(_now_utc())
        transitions = {"received": ["running", "failed"], "running": ["succeeded", "failed"], "succeeded": [], "failed": []}
        for r in trs:
            if r.get("id") == req_row["id"]:
                cur = r.get("status")
                if status != cur and status not in transitions.get(cur, []):
                    _save("tool_requests.json", trs)
                    return _err("INVALID_TRANSITION", f"Illegal tool_requests status transition {cur} -> {status}.")
                r["status"] = status
                r["updated_at"] = now2
                if http_status is not None:
                    r["http_status"] = http_status
                if duration_ms is not None:
                    if not isinstance(duration_ms, int) or duration_ms < 0:
                        _save("tool_requests.json", trs)
                        return _err("VALIDATION_ERROR", "duration_ms must be an integer >= 0.")
                    r["duration_ms"] = duration_ms
                if result_count is not None:
                    if not isinstance(result_count, int) or result_count < 0:
                        _save("tool_requests.json", trs)
                        return _err("VALIDATION_ERROR", "result_count must be an integer >= 0.")
                    r["result_count"] = result_count
                if status == "failed":
                    if error_code is None or error_message is None:
                        _save("tool_requests.json", trs)
                        return _err("VALIDATION_ERROR", "Failed requests must include error_code and error_message.")
                    r["error_code"] = str(error_code)
                    r["error_message"] = str(error_message)
                if status == "succeeded":
                    r["error_code"] = None
                    r["error_message"] = None
                break
        _save("tool_requests.json", trs)
        return None

    e = _update_req("running")
    if e:
        return e

    # ---- Read rollups ----
    usage_rollups = _load("usage_rollups.json")

    window_start = None
    if window == "day":
        # UTC start of day
        window_start = datetime.datetime(day_date.year, day_date.month, day_date.day, tzinfo=datetime.timezone.utc).isoformat().replace("+00:00", "Z")

    # Primary row: session + all tools
    row = None
    for u in usage_rollups:
        if u.get("scope") == "session" and u.get("session_id") == session_id and u.get("tool_name") is None and u.get("window") == window and u.get("window_start") == window_start:
            row = u
            break
    if row is None:
        # Return zeros if none exist (read tools should not error on empty)
        row = {
            "scope": "session",
            "session_id": session_id,
            "tool_name": None,
            "window": window,
            "window_start": window_start,
            "request_count": 0,
            "success_count": 0,
            "error_count": 0,
            "cache_hit_count": 0,
            "upstream_call_count": 0,
            "total_duration_ms": 0,
        }

    per_tool = []
    for u in usage_rollups:
        if u.get("scope") == "session" and u.get("session_id") == session_id and u.get("tool_name") is not None and u.get("window") == window and u.get("window_start") == window_start:
            per_tool.append({
                "tool_name": u.get("tool_name"),
                "request_count": u.get("request_count", 0),
                "success_count": u.get("success_count", 0),
                "error_count": u.get("error_count", 0),
                "cache_hit_count": u.get("cache_hit_count", 0),
                "upstream_call_count": u.get("upstream_call_count", 0),
                "total_duration_ms": u.get("total_duration_ms", 0),
            })
    per_tool.sort(key=lambda x: (x["tool_name"] or ""))

    payload = {
        "scope": "session",
        "session_id": session_id,
        "window": window,
        "day": day if window == "day" else None,
        "all_tools": {
            "request_count": row.get("request_count", 0),
            "success_count": row.get("success_count", 0),
            "error_count": row.get("error_count", 0),
            "cache_hit_count": row.get("cache_hit_count", 0),
            "upstream_call_count": row.get("upstream_call_count", 0),
            "total_duration_ms": row.get("total_duration_ms", 0),
        },
        "per_tool": per_tool,
    }

    dur = int((time.perf_counter() - start) * 1000)
    e = _update_req("succeeded", duration_ms=dur, http_status=200, result_count=1)
    if e:
        return e

    # increment rollups for this request itself (terminal transition bumps happen in other tools; here we must do it too)
    # Reuse minimal bump logic for all_time only; day window rollups are not incremented by tools currently.
    usage_rollups2 = _load("usage_rollups.json")
    now3 = _iso(_now_utc())
    def _find_or_create(scope, sid, tname):
        for u in usage_rollups2:
            if u.get("scope") == scope and u.get("session_id") == sid and u.get("tool_name") == tname and u.get("window") == "all_time" and u.get("window_start") is None:
                return u
        newr = {
            "id": _new_id("hcs_usage"),
            "scope": scope,
            "session_id": sid,
            "tool_name": tname,
            "window": "all_time",
            "window_start": None,
            "request_count": 0,
            "success_count": 0,
            "error_count": 0,
            "cache_hit_count": 0,
            "upstream_call_count": 0,
            "total_duration_ms": 0,
            "created_at": now3,
            "updated_at": now3,
        }
        usage_rollups2.append(newr)
        return newr
    def _bump(u):
        u["request_count"] += 1
        u["success_count"] += 1
        u["upstream_call_count"] = max(0, int(u["request_count"]) - int(u["cache_hit_count"]))
        u["total_duration_ms"] += dur
        u["updated_at"] = now3
    _bump(_find_or_create("session", session_id, None))
    _bump(_find_or_create("session", session_id, "get_usage_stats"))
    _bump(_find_or_create("global", None, None))
    _bump(_find_or_create("global", None, "get_usage_stats"))
    _save("usage_rollups.json", usage_rollups2)

    return payload

def get_all_usage_stats(window=None, day=None, **_extra):
    import json, os, datetime, re, time, uuid

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0466000" if __import__("os").path.isdir("./environment_mix/0466000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    def _now_utc():
        return datetime.datetime.now(datetime.timezone.utc)

    def _iso(dt):
        if isinstance(dt, datetime.datetime):
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc).isoformat().replace("+00:00", "Z")
        return dt

    def _new_id(prefix):
        alphabet = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
        ts = int(time.time() * 1000)
        out = []
        for _ in range(10):
            out.append(alphabet[ts % 32])
            ts //= 32
        rand = uuid.uuid4().int
        for _ in range(16):
            out.append(alphabet[rand % 32])
            rand //= 32
        return f"{prefix}_" + "".join(reversed(out))

    def _parse_day(s):
        if not isinstance(s, str):
            return None
        try:
            return datetime.date.fromisoformat(s)
        except ValueError:
            return None

    # ---- Authorization (ambient) ----
    # Permit access only if there exists at least one active session in the store.
    sessions = _load("sessions.json")
    authorized_session = None
    now = _now_utc()
    for s in sessions:
        if s.get("status") == "active":
            exp = s.get("expires_at")
            if exp:
                try:
                    dt = datetime.datetime.fromisoformat(exp[:-1] + "+00:00") if isinstance(exp, str) and exp.endswith("Z") else datetime.datetime.fromisoformat(exp)
                    if dt.tzinfo is None:
                        dt = dt.replace(tzinfo=datetime.timezone.utc)
                    if dt <= now:
                        continue
                except ValueError:
                    # ignore malformed expires_at for auth check
                    pass
            authorized_session = s
            break
    if authorized_session is None:
        return _err("UNAUTHORIZED", "Not permitted to access global usage statistics.")

    # ---- Validate inputs ----
    if window is None:
        window = "all_time"
    if not isinstance(window, str) or window not in ("all_time", "day"):
        return _err("VALIDATION_ERROR", "window must be one of: all_time, day.")
    day_date = None
    if window == "day":
        day_date = _parse_day(day)
        if day_date is None:
            return _err("VALIDATION_ERROR", "day must be provided as YYYY-MM-DD when window='day'.")

    # ---- Record request under an authorized session ----
    tool_requests = _load("tool_requests.json")
    created_at = _iso(now)
    req_row = {
        "id": _new_id("hcs_trq"),
        "session_id": authorized_session.get("id"),
        "tool_name": "get_all_usage_stats",
        "input_params": {"window": window, "day": day},
        "normalized_cache_key": None,
        "status": "received",
        "http_status": None,
        "error_code": None,
        "error_message": None,
        "duration_ms": None,
        "result_count": None,
        "cache_hit": False,
        "created_at": created_at,
        "updated_at": created_at,
    }
    tool_requests.append(req_row)
    _save("tool_requests.json", tool_requests)

    start = time.perf_counter()

    def _update_req(status, duration_ms=None, error_code=None, error_message=None, http_status=None, result_count=None):
        trs = _load("tool_requests.json")
        now2 = _iso(_now_utc())
        transitions = {"received": ["running", "failed"], "running": ["succeeded", "failed"], "succeeded": [], "failed": []}
        for r in trs:
            if r.get("id") == req_row["id"]:
                cur = r.get("status")
                if status != cur and status not in transitions.get(cur, []):
                    _save("tool_requests.json", trs)
                    return _err("INVALID_TRANSITION", f"Illegal tool_requests status transition {cur} -> {status}.")
                r["status"] = status
                r["updated_at"] = now2
                if http_status is not None:
                    r["http_status"] = http_status
                if duration_ms is not None:
                    if not isinstance(duration_ms, int) or duration_ms < 0:
                        _save("tool_requests.json", trs)
                        return _err("VALIDATION_ERROR", "duration_ms must be an integer >= 0.")
                    r["duration_ms"] = duration_ms
                if result_count is not None:
                    if not isinstance(result_count, int) or result_count < 0:
                        _save("tool_requests.json", trs)
                        return _err("VALIDATION_ERROR", "result_count must be an integer >= 0.")
                    r["result_count"] = result_count
                if status == "failed":
                    if error_code is None or error_message is None:
                        _save("tool_requests.json", trs)
                        return _err("VALIDATION_ERROR", "Failed requests must include error_code and error_message.")
                    r["error_code"] = str(error_code)
                    r["error_message"] = str(error_message)
                if status == "succeeded":
                    r["error_code"] = None
                    r["error_message"] = None
                break
        _save("tool_requests.json", trs)
        return None

    e = _update_req("running")
    if e:
        return e

    usage_rollups = _load("usage_rollups.json")
    window_start = None
    if window == "day":
        window_start = datetime.datetime(day_date.year, day_date.month, day_date.day, tzinfo=datetime.timezone.utc).isoformat().replace("+00:00", "Z")

    # Global all tools
    row = None
    for u in usage_rollups:
        if u.get("scope") == "global" and u.get("session_id") is None and u.get("tool_name") is None and u.get("window") == window and u.get("window_start") == window_start:
            row = u
            break
    if row is None:
        row = {
            "scope": "global",
            "session_id": None,
            "tool_name": None,
            "window": window,
            "window_start": window_start,
            "request_count": 0,
            "success_count": 0,
            "error_count": 0,
            "cache_hit_count": 0,
            "upstream_call_count": 0,
            "total_duration_ms": 0,
        }

    per_tool = []
    for u in usage_rollups:
        if u.get("scope") == "global" and u.get("session_id") is None and u.get("tool_name") is not None and u.get("window") == window and u.get("window_start") == window_start:
            per_tool.append({
                "tool_name": u.get("tool_name"),
                "request_count": u.get("request_count", 0),
                "success_count": u.get("success_count", 0),
                "error_count": u.get("error_count", 0),
                "cache_hit_count": u.get("cache_hit_count", 0),
                "upstream_call_count": u.get("upstream_call_count", 0),
                "total_duration_ms": u.get("total_duration_ms", 0),
            })
    per_tool.sort(key=lambda x: (x["tool_name"] or ""))

    payload = {
        "scope": "global",
        "window": window,
        "day": day if window == "day" else None,
        "all_tools": {
            "request_count": row.get("request_count", 0),
            "success_count": row.get("success_count", 0),
            "error_count": row.get("error_count", 0),
            "cache_hit_count": row.get("cache_hit_count", 0),
            "upstream_call_count": row.get("upstream_call_count", 0),
            "total_duration_ms": row.get("total_duration_ms", 0),
        },
        "per_tool": per_tool,
    }

    dur = int((time.perf_counter() - start) * 1000)
    e = _update_req("succeeded", duration_ms=dur, http_status=200, result_count=1)
    if e:
        return e

    # Increment all_time usage_rollups for this request (same pattern as get_usage_stats)
    usage_rollups2 = _load("usage_rollups.json")
    now3 = _iso(_now_utc())
    def _find_or_create(scope, sid, tname):
        for u in usage_rollups2:
            if u.get("scope") == scope and u.get("session_id") == sid and u.get("tool_name") == tname and u.get("window") == "all_time" and u.get("window_start") is None:
                return u
        newr = {
            "id": _new_id("hcs_usage"),
            "scope": scope,
            "session_id": sid,
            "tool_name": tname,
            "window": "all_time",
            "window_start": None,
            "request_count": 0,
            "success_count": 0,
            "error_count": 0,
            "cache_hit_count": 0,
            "upstream_call_count": 0,
            "total_duration_ms": 0,
            "created_at": now3,
            "updated_at": now3,
        }
        usage_rollups2.append(newr)
        return newr
    def _bump(u):
        u["request_count"] += 1
        u["success_count"] += 1
        u["upstream_call_count"] = max(0, int(u["request_count"]) - int(u["cache_hit_count"]))
        u["total_duration_ms"] += dur
        u["updated_at"] = now3
    sid = authorized_session.get("id")
    _bump(_find_or_create("session", sid, None))
    _bump(_find_or_create("session", sid, "get_all_usage_stats"))
    _bump(_find_or_create("global", None, None))
    _bump(_find_or_create("global", None, "get_all_usage_stats"))
    _save("usage_rollups.json", usage_rollups2)

    return payload

def create_session(client_id, session_token, ip_address=None, user_agent=None, expires_at=None, **_extra):
    import json, os, datetime, re, hashlib, time, uuid

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0466000" if __import__("os").path.isdir("./environment_mix/0466000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    def _now_utc():
        return datetime.datetime.now(datetime.timezone.utc)

    def _iso(dt):
        if isinstance(dt, datetime.datetime):
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc).isoformat().replace("+00:00", "Z")
        return dt

    def _parse_dt(s):
        if s is None:
            return None
        if not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                return datetime.datetime.fromisoformat(s[:-1] + "+00:00")
            return datetime.datetime.fromisoformat(s)
        except ValueError:
            return None

    def _new_id(prefix):
        alphabet = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
        ts = int(time.time() * 1000)
        out = []
        for _ in range(10):
            out.append(alphabet[ts % 32])
            ts //= 32
        rand = uuid.uuid4().int
        for _ in range(16):
            out.append(alphabet[rand % 32])
            rand //= 32
        return f"{prefix}_" + "".join(reversed(out))

    # ---- Validate inputs ----
    if not isinstance(client_id, str) or len(client_id.strip()) < 1:
        return _err("VALIDATION_ERROR", "client_id must be a non-empty string.")
    if not isinstance(session_token, str) or len(session_token) < 16:
        return _err("VALIDATION_ERROR", "session_token must be a string with minLength 16.")
    if ip_address is not None and not isinstance(ip_address, str):
        return _err("VALIDATION_ERROR", "ip_address must be a string.")
    if user_agent is not None and not isinstance(user_agent, str):
        return _err("VALIDATION_ERROR", "user_agent must be a string.")
    exp_dt = None
    if expires_at is not None:
        exp_dt = _parse_dt(expires_at)
        if exp_dt is None:
            return _err("VALIDATION_ERROR", "expires_at must be an RFC3339/ISO-8601 date-time string.")
        if exp_dt.tzinfo is None:
            exp_dt = exp_dt.replace(tzinfo=datetime.timezone.utc)

    now = _now_utc()
    if exp_dt is not None and exp_dt <= now:
        return _err("VALIDATION_ERROR", "expires_at must not be in the past.")

    # Default TTL if omitted
    if exp_dt is None:
        exp_dt = now + datetime.timedelta(days=7)

    # ---- Hash token (never store raw) ----
    token_hash = hashlib.sha256(session_token.encode("utf-8")).hexdigest()

    sessions = _load("sessions.json")
    # enforce unique(session_token_hash)
    for s in sessions:
        if s.get("session_token_hash") == token_hash:
            # If existing session is active and not expired, idempotently return it
            status = s.get("status")
            existing_exp = _parse_dt(s.get("expires_at"))
            if existing_exp is not None and existing_exp.tzinfo is None:
                existing_exp = existing_exp.replace(tzinfo=datetime.timezone.utc)
            if status == "active" and (existing_exp is None or existing_exp > now):
                return {
                    "session_id": s.get("id"),
                    "status": s.get("status"),
                    "client_id": s.get("client_id"),
                    "expires_at": s.get("expires_at"),
                    "created_at": s.get("created_at"),
                    "updated_at": s.get("updated_at"),
                }
            # otherwise conflict: uniqueness prevents creating another with same token hash
            return _err("CONFLICT", "A session with this session_token already exists and cannot be recreated.")

    created_at = _iso(now)
    exp_iso = _iso(exp_dt)

    # Constraint: expires_at is null OR expires_at >= created_at (satisfied)
    sess_id = _new_id("hcs_sess")
    row = {
        "id": sess_id,
        "session_token_hash": token_hash,
        "client_id": client_id.strip(),
        "ip_address": ip_address,
        "user_agent": user_agent,
        "status": "active",
        "last_seen_at": None,
        "expires_at": exp_iso,
        "created_at": created_at,
        "updated_at": created_at,
    }
    sessions.append(row)
    _save("sessions.json", sessions)

    return {
        "session_id": sess_id,
        "status": row["status"],
        "client_id": row["client_id"],
        "expires_at": row["expires_at"],
        "created_at": row["created_at"],
        "updated_at": row["updated_at"],
    }

def list_tool_requests(session_id=None, tool_name=None, status=None, cache_hit=None, limit=None, cursor=None, **_extra):
    import json, os, datetime, re, time, hashlib

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0466000" if __import__("os").path.isdir("./environment_mix/0466000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.now(datetime.timezone.utc)

    def _now_iso():
        return _now().replace(microsecond=0).isoformat().replace("+00:00", "Z")

    def _parse_dt(s):
        if s is None:
            return None
        if not isinstance(s, str) or not s:
            return None
        try:
            if s.endswith("Z"):
                s = s[:-1] + "+00:00"
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    def _ulid_like(prefix, v):
        if v is None:
            return True
        if not isinstance(v, str):
            return False
        pat = r"^" + re.escape(prefix) + r"_[0-9A-HJKMNP-TV-Z]{10,}$"
        return re.match(pat, v) is not None

    def _new_id(prefix):
        alphabet = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
        ms = int(time.time() * 1000)
        t = ms
        out = []
        for _ in range(10):
            out.append(alphabet[t % 32])
            t //= 32
        out = list(reversed(out))
        import random
        out.extend(alphabet[random.randrange(32)] for _ in range(16))
        return f"{prefix}_{''.join(out)}"

    def _resolve_active_session_for_ambient():
        sessions = _load("sessions.json")
        now = _now()
        for s in sessions:
            if s.get("status") != "active":
                continue
            exp = _parse_dt(s.get("expires_at"))
            if exp is not None and exp <= now:
                continue
            return s
        return None

    def _transition_tool_request(tr_row, new_status, http_status=None, error_code=None, error_message=None, duration_ms=None, result_count=None, cache_hit=None, normalized_cache_key=None):
        allowed = {
            "received": {"running", "failed"},
            "running": {"succeeded", "failed"},
            "succeeded": set(),
            "failed": set(),
        }
        cur = tr_row.get("status")
        if cur not in allowed or new_status not in allowed[cur]:
            return False
        now_iso = _now_iso()
        tr_row["status"] = new_status
        tr_row["updated_at"] = now_iso
        if http_status is not None:
            tr_row["http_status"] = http_status
        if normalized_cache_key is not None:
            tr_row["normalized_cache_key"] = normalized_cache_key
        if cache_hit is not None:
            tr_row["cache_hit"] = bool(cache_hit)
        if new_status == "failed":
            tr_row["error_code"] = error_code if error_code is not None else "INTERNAL_ERROR"
            tr_row["error_message"] = error_message if error_message is not None else "Request failed"
        if new_status == "succeeded":
            tr_row["error_code"] = None
            tr_row["error_message"] = None
        if duration_ms is not None:
            tr_row["duration_ms"] = duration_ms
        if result_count is not None:
            tr_row["result_count"] = result_count
        return True

    def _upsert_rollup(rollups, scope, session_id_val, tool_name_val, window, window_start, now_iso):
        for r in rollups:
            if r.get("scope") == scope and r.get("session_id") == session_id_val and r.get("tool_name") == tool_name_val and r.get("window") == window and r.get("window_start") == window_start:
                r["updated_at"] = now_iso
                return r
        r = {
            "id": _new_id("hcs_usage"),
            "scope": scope,
            "session_id": session_id_val,
            "tool_name": tool_name_val,
            "window": window,
            "window_start": window_start,
            "request_count": 0,
            "success_count": 0,
            "error_count": 0,
            "cache_hit_count": 0,
            "upstream_call_count": 0,
            "total_duration_ms": 0,
            "created_at": now_iso,
            "updated_at": now_iso,
        }
        rollups.append(r)
        return r

    def _increment_rollups_for_completion(session_id_val, tool_name_val, succeeded, cache_hit_val, duration_ms_val):
        rollups = _load("usage_rollups.json")
        now_iso = _now_iso()
        dur = int(duration_ms_val) if isinstance(duration_ms_val, int) and duration_ms_val >= 0 else 0
        ch = bool(cache_hit_val)

        targets = [
            ("session", session_id_val, None),
            ("session", session_id_val, tool_name_val),
            ("global", None, None),
            ("global", None, tool_name_val),
        ]
        for scope, sid, tname in targets:
            row = _upsert_rollup(rollups, scope, sid, tname, "all_time", None, now_iso)
            row["request_count"] = int(row.get("request_count") or 0) + 1
            if succeeded:
                row["success_count"] = int(row.get("success_count") or 0) + 1
            else:
                row["error_count"] = int(row.get("error_count") or 0) + 1
            if ch:
                row["cache_hit_count"] = int(row.get("cache_hit_count") or 0) + 1
            row["upstream_call_count"] = max(0, int(row.get("request_count") or 0) - int(row.get("cache_hit_count") or 0))
            row["total_duration_ms"] = int(row.get("total_duration_ms") or 0) + dur

            if int(row["success_count"]) + int(row["error_count"]) > int(row["request_count"]):
                row["request_count"] = int(row["success_count"]) + int(row["error_count"])
            if int(row["cache_hit_count"]) > int(row["request_count"]):
                row["cache_hit_count"] = int(row["request_count"])
                row["upstream_call_count"] = max(0, int(row["request_count"]) - int(row["cache_hit_count"]))

        _save("usage_rollups.json", rollups)

    def _log_list_request(session_row, input_params, status, http_status=None, error_code=None, error_message=None, duration_ms=None, result_count=None):
        tool_requests = _load("tool_requests.json")
        now_iso = _now_iso()
        tr = {
            "id": _new_id("hcs_tr"),
            "session_id": session_row["id"],
            "tool_name": "get_all_usage_stats" if False else "get_usage_stats" if False else "get_tool_request" if False else "list_tool_requests",
            "input_params": input_params,
            "normalized_cache_key": None,
            "status": "received",
            "http_status": None,
            "error_code": None,
            "error_message": None,
            "duration_ms": None,
            "result_count": None,
            "cache_hit": False,
            "created_at": now_iso,
            "updated_at": now_iso,
        }
        tool_requests.append(tr)
        _save("tool_requests.json", tool_requests)

        _transition_tool_request(tr, "running")
        _save("tool_requests.json", tool_requests)

        if status == "succeeded":
            _transition_tool_request(tr, "succeeded", http_status=http_status, duration_ms=duration_ms, result_count=result_count, cache_hit=False)
            _save("tool_requests.json", tool_requests)
            _increment_rollups_for_completion(tr["session_id"], tr["tool_name"], True, False, duration_ms or 0)
        else:
            _transition_tool_request(tr, "failed", http_status=http_status, error_code=error_code, error_message=error_message, duration_ms=duration_ms, result_count=result_count, cache_hit=False)
            _save("tool_requests.json", tool_requests)
            _increment_rollups_for_completion(tr["session_id"], tr["tool_name"], False, False, duration_ms or 0)

    t0 = time.time()

    # Ambient auth: pick any active, unexpired session.
    sess = _resolve_active_session_for_ambient()
    if not sess:
        return _err("UNAUTHORIZED", "No active session available.")

    # Reject if resolved session itself is not eligible (business rule).
    now = _now()
    if sess.get("status") != "active":
        return _err("UNAUTHORIZED", "Session is not active.")
    exp = _parse_dt(sess.get("expires_at"))
    if exp is not None and exp <= now:
        return _err("UNAUTHORIZED", "Session is expired.")

    # Validate filters (relax cursor: opaque string allowed; do not require ULID pattern).
    if session_id is not None:
        if not isinstance(session_id, str) or not _ulid_like("hcs_sess", session_id):
            dur = max(0, int((time.time() - t0) * 1000))
            _log_list_request(sess, {"session_id": session_id, "tool_name": tool_name, "status": status, "cache_hit": cache_hit, "limit": limit, "cursor": cursor}, "failed",
                              http_status=400, error_code="VALIDATION_ERROR", error_message="session_id is invalid.", duration_ms=dur, result_count=0)
            return _err("VALIDATION_ERROR", "session_id is invalid.")
        # If they filter by a session id that doesn't exist, return empty (not error).
    if tool_name is not None:
        allowed_tools = {"fda_drug_lookup", "pubmed_search", "health_topics", "clinical_trials_search", "lookup_icd_code"}
        if not isinstance(tool_name, str) or tool_name not in allowed_tools:
            dur = max(0, int((time.time() - t0) * 1000))
            _log_list_request(sess, {"session_id": session_id, "tool_name": tool_name, "status": status, "cache_hit": cache_hit, "limit": limit, "cursor": cursor}, "failed",
                              http_status=400, error_code="VALIDATION_ERROR", error_message="tool_name is invalid.", duration_ms=dur, result_count=0)
            return _err("VALIDATION_ERROR", "tool_name is invalid.")
    if status is not None:
        allowed_status = {"received", "running", "succeeded", "failed"}
        if not isinstance(status, str) or status not in allowed_status:
            dur = max(0, int((time.time() - t0) * 1000))
            _log_list_request(sess, {"session_id": session_id, "tool_name": tool_name, "status": status, "cache_hit": cache_hit, "limit": limit, "cursor": cursor}, "failed",
                              http_status=400, error_code="VALIDATION_ERROR", error_message="status is invalid.", duration_ms=dur, result_count=0)
            return _err("VALIDATION_ERROR", "status is invalid.")
    if cache_hit is not None and not isinstance(cache_hit, bool):
        dur = max(0, int((time.time() - t0) * 1000))
        _log_list_request(sess, {"session_id": session_id, "tool_name": tool_name, "status": status, "cache_hit": cache_hit, "limit": limit, "cursor": cursor}, "failed",
                          http_status=400, error_code="VALIDATION_ERROR", error_message="cache_hit must be boolean.", duration_ms=dur, result_count=0)
        return _err("VALIDATION_ERROR", "cache_hit must be boolean.")
    if limit is None:
        limit = 50
    if not isinstance(limit, int) or limit < 1 or limit > 200:
        dur = max(0, int((time.time() - t0) * 1000))
        _log_list_request(sess, {"session_id": session_id, "tool_name": tool_name, "status": status, "cache_hit": cache_hit, "limit": limit, "cursor": cursor}, "failed",
                          http_status=400, error_code="VALIDATION_ERROR", error_message="limit is invalid.", duration_ms=dur, result_count=0)
        return _err("VALIDATION_ERROR", "limit is invalid.")
    if cursor is not None and not isinstance(cursor, str):
        dur = max(0, int((time.time() - t0) * 1000))
        _log_list_request(sess, {"session_id": session_id, "tool_name": tool_name, "status": status, "cache_hit": cache_hit, "limit": limit, "cursor": cursor}, "failed",
                          http_status=400, error_code="VALIDATION_ERROR", error_message="cursor is invalid.", duration_ms=dur, result_count=0)
        return _err("VALIDATION_ERROR", "cursor is invalid.")

    # Fetch and filter rows.
    rows = _load("tool_requests.json")
    if not isinstance(rows, list):
        rows = []

    # Sort most recent first by created_at then id.
    def _sort_key(r):
        dt = _parse_dt(r.get("created_at")) or datetime.datetime(1970, 1, 1, tzinfo=datetime.timezone.utc)
        return (dt, r.get("id") or "")

    rows_sorted = sorted(rows, key=_sort_key, reverse=True)

    # Apply filters.
    filtered = []
    for r in rows_sorted:
        if session_id is not None and r.get("session_id") != session_id:
            continue
        if tool_name is not None and r.get("tool_name") != tool_name:
            continue
        if status is not None and r.get("status") != status:
            continue
        if cache_hit is not None and bool(r.get("cache_hit")) != cache_hit:
            continue
        filtered.append(r)

    # Pagination: cursor is opaque; interpret as "start after this id in the filtered/sorted list".
    start_index = 0
    if cursor:
        # If cursor not found, do not error; treat as starting from beginning (opaque cursor semantics vary).
        for i, r in enumerate(filtered):
            if r.get("id") == cursor:
                start_index = i + 1
                break

    page = filtered[start_index:start_index + limit]
    has_more = start_index + limit < len(filtered)
    next_cursor = page[-1].get("id") if (has_more and page) else None

    dur = max(0, int((time.time() - t0) * 1000))
    _log_list_request(
        sess,
        {"session_id": session_id, "tool_name": tool_name, "status": status, "cache_hit": cache_hit, "limit": limit, "cursor": cursor},
        "succeeded",
        http_status=200,
        duration_ms=dur,
        result_count=len(page),
    )

    return {
        "data": page,
        "meta": {
            "total": len(filtered),
            "limit": limit,
            "has_more": has_more,
            "next_cursor": next_cursor,
        },
    }
